      var overflowX = (style && (style.overflowX || style.overflow)) || '';
      var overflowY = (style && (style.overflowY || style.overflow)) || '';
      var clipsX = overflowX && overflowX !== 'visible';
      var clipsY = overflowY && overflowY !== 'visible';
